"""Regenerates assets/sample-pdf.js from assets/sample.pdf.

Pages opened straight from disk (file://) can't fetch() the PDF, so the notes
page falls back to this base64 copy. Run after rebuilding sample.pdf:
    python assets/make-sample-pdf-js.py
"""
import base64
from pathlib import Path

here = Path(__file__).parent
data = base64.b64encode((here / "sample.pdf").read_bytes()).decode("ascii")
(here / "sample-pdf.js").write_text(
    "// Generated by make-sample-pdf-js.py from sample.pdf. Do not edit.\n"
    f'window.SAMPLE_PDF_BASE64 = "{data}";\n',
    encoding="utf-8",
)
print(f"Wrote sample-pdf.js ({len(data) // 1024} KB)")
